# Time-series tables -> TimescaleDB hypertables (PostgreSQL with the extension
# available only; plain tables elsewhere, so SQLite/vanilla Postgres still work).
HYPERTABLES = {
    # table: (time column, chunk interval)
    "usage_samples": ("ts", "1 day"),
    "node_samples": ("ts", "7 days"),
    "cost_allocations": ("window_start", "7 days"),
    "node_costs": ("window_start", "7 days"),
}
RAW_SAMPLE_RETENTION = "35 days"  # right-sizing needs 14 days; keep headroom
COMPRESS_AFTER = "3 days"


def _enable_timescale() -> None:
    bind = op.get_bind()
    if bind.dialect.name != "postgresql":
        return
    available = bind.execute(
        sa.text("SELECT 1 FROM pg_available_extensions WHERE name = 'timescaledb'")
    ).scalar()
    if not available:
        return
    op.execute("CREATE EXTENSION IF NOT EXISTS timescaledb")
    for table, (col, chunk) in HYPERTABLES.items():
        op.execute(
            f"SELECT create_hypertable('{table}', '{col}', chunk_time_interval => INTERVAL '{chunk}', "
            "migrate_data => TRUE, if_not_exists => TRUE)"
        )
    op.execute(
        "ALTER TABLE usage_samples SET (timescaledb.compress, "
        "timescaledb.compress_segmentby = 'cluster_id, namespace', timescaledb.compress_orderby = 'ts DESC')"
    )
    op.execute(f"SELECT add_compression_policy('usage_samples', INTERVAL '{COMPRESS_AFTER}', if_not_exists => TRUE)")
    op.execute(
        f"SELECT add_retention_policy('usage_samples', INTERVAL '{RAW_SAMPLE_RETENTION}', if_not_exists => TRUE)"
    )


